# Surah Hud (chapter 11) — part 9: ayat 81-90 (IDs 1554-1563)
SURAH = 11

ENTRIES = {
1554: (
"انہوں نے — کہا — اے لوطؑ — ہم — تمہارے رب — کے فرشتے — ہیں — وہ — تم تک — ہرگز — نہیں پہنچیں گے — پس — آپ — اپنے اہل — کو لے کر — رات کے ایک حصے — میں — روانہ — ہوں — اور — تم میں سے — کوئی بھی — پیچھے — نہ دیکھے — مگر — آپ کی بیوی — ان — کو وہ — مصیبت — پہنچنے — والی ہے — جو — ان — سب — پر — پہنچنے — والی ہے — ان — کا وعدہ — صبح ہے — کیا — صبح — قریب نہیں",
"""۱۔ فرشتوں نے لوطؑ — کو — رات — میں — روانہ ہونے کا حکم دیا؛ بیوی — پیچھے — رہنے والی۔
۲۔ ’’قَالُوا يَا لُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوا إِلَيْكَ فَأَسْرِ بِأَهْلِكَ بِقِطْعٍ مِّنَ اللَّيْلِ وَلَا يَلْتَفِتْ مِّنكُمْ أَحَدٌ إِلَّا امْرَأَتَكَ إِنَّهُ مُصِيبُهَا مَا أَصَابَهُمْ إِنَّ مَوْعِدَهُمُ الصُّبْحُ أَلَيْسَ الصُّبْحُ بِقَرِيبٍ‘‘ — انہوں نے — کہا — اے لوطؑ — ہم — تمہارے رب — کے فرشتے — ہیں — وہ — تم تک — ہرگز — نہیں پہنچیں گے — پس — آپ — اپنے اہل — کو لے کر — رات کے ایک حصے — میں — روانہ — ہوں — اور — تم میں سے — کوئی بھی — پیچھے — نہ دیکھے — مگر — آپ کی بیوی — ان — کو وہ — مصیبت — پہنچنے — والی ہے — جو — ان — سب — پر — پہنچنے — والی ہے — ان — کا وعدہ — صبح ہے — کیا — صبح — قریب نہیں — یعنی فرشتوں نے کہا — اے لوطؑ — ہم تمہارے رب کے فرشتے ہیں — وہ تم تک — نہیں پہنچ سکیں گے — رات کے ایک حصے — میں — اپنے اہل — کو — لے کر روانہ — ہو جاؤ — اور کوئی پیچھے — نہ دیکھے؛ آپ کی بیوی — ان — پر پڑنے والی مصیبت — میں — شامل ہے — ان کا وعدہ — صبح ہے — کیا — صبح — قریب نہیں۔
۳۔ عملی سبق: اللہ کے حکم — کی فوری اطاعت — نجات — کا ذریعہ ہے۔"""
),
1555: (
"پس — جب — ہمارا حکم — آیا — ہم نے — ان کی — اُوپر والی — بستیاں — نیچے — کر دی — اور — ان — پر — سخت — پہاڑی پتھر برسائے — تہہ در تہہ",
"""۱۔ عذاب — لوطؑ کی قوم — پر — الٹی ہوئی بستیاں اور پتھر کی بارش۔
۲۔ ’’فَلَمَّا جَاءَ أَمْرُنَا جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَۃً مِّن سِجِّيلٍ مَّنضُودٍ‘‘ — پس — جب — ہمارا حکم — آیا — ہم نے — ان کی — اُوپر والی — بستیاں — نیچے — کر دی — اور — ان — پر — سخت — پہاڑی پتھر برسائے — تہہ در تہہ — یعنی جب ہمارا حکم آیا — ہم نے — ان — کی — بستیاں — الٹ دی — اور — ان — پر — سخت — پہاڑوں جیسے پتھر برسائے — تہہ در تہہ۔
۳۔ عملی سبق: بے حیائی — بستیوں — کو — تباہ — کر دیتی ہے۔"""
),
1556: (
"معین نشان — آپ کے رب — کے ہاں — اور — وہ — ظالموں — سے — دور — نہیں",
"""۱۔ عذاب کے پتھر — نشان والے — ظالموں سے دور نہیں۔
۲۔ ’’مُّسَوَّمَۃً عِندَ رَبِّكَ وَمَا هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ‘‘ — معین نشان — آپ کے رب — کے ہاں — اور — وہ — ظالموں — سے — دور — نہیں — یعنی یہ — عذاب کے پتھر — آپ کے رب کے ہاں نشان — والے ہیں — اور — وہ — ظالموں — سے — دور — نہیں۔
۳۔ عملی سبق: عذاب — ظالموں — سے — دور — نہیں ہوتا۔"""
),
1557: (
"اور — مدین — کی طرف — ان کے بھائی — شعیبؑ — کو بھیجا — انہوں نے کہا — اے — میری قوم — اللہ — کی عبادت کرو — اس — کے سوا — تمہارا — کوئی معبود — نہیں — اور — پیمانہ اور تول — کم نہ کرو — بے شک — میں — تم — کو — بھلائی کی حالت — میں دیکھتا ہوں — اور — بے شک — میں — تم — پر — ایک گھیرنے والے دن — کے عذاب سے — ڈرتا ہوں",
"""۱۔ شعیبؑ — مدین — کی طرف بھیجے گئے — ناپ تول — درست کرنے کا حکم۔
۲۔ ’’وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ وَلَا تَنقُصُوا الْمِكْيَالَ وَالْمِيزَانَ إِنِّي أَرَاكُم بِخَيْرٍ وَإِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ مُّحِيطٍ‘‘ — اور — مدین — کی طرف — ان کے بھائی — شعیبؑ — کو بھیجا — انہوں نے کہا — اے — میری قوم — اللہ — کی عبادت کرو — اس — کے سوا — تمہارا — کوئی معبود — نہیں — اور — پیمانہ اور تول — کم نہ کرو — بے شک — میں — تم — کو — بھلائی کی حالت — میں دیکھتا ہوں — اور — بے شک — میں — تم — پر — ایک گھیرنے والے دن — کے عذاب سے — ڈرتا ہوں — یعنی مدین — کی طرف — شعیبؑ کو بھیجا — اے قوم — اللہ کی عبادت کرو — اس کے سوا — تمہارا معبود — نہیں — اور پیمانہ اور تول — کم نہ کرو — میں — تم — کو — بھلائی کی حالت — میں دیکھتا ہوں — اور — میں — تم پر — ایک گھیرنے والے — دن کے عذاب — سے ڈرتا ہوں۔
۳۔ عملی سبق: ناپ تول — میں انصاف — سب سے — بڑا اخلاقی فریضہ — ہے۔"""
),
1558: (
"اور — اے میری قوم — لگاتار — پیمانہ اور تول — انصاف کے ساتھ — پورا — کرو — اور — لوگوں کو — ان — کی چیزیں — کم نہ کرو — اور — زمین میں — فساد نہ کرو — فسادی — ہو کر",
"""۱۔ ناپ تول — پورا کرو — فساد نہ کرو۔
۲۔ ’’وَيَا قَوْمِ أَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ‘‘ — اور — اے میری قوم — لگاتار — پیمانہ اور تول — انصاف کے ساتھ — پورا — کرو — اور — لوگوں کو — ان — کی چیزیں — کم نہ کرو — اور — زمین میں — فساد نہ کرو — فسادی — ہو کر — یعنی اے میری قوم — انصاف کے ساتھ — پیمانہ اور تول — پورا کرو — اور لوگوں کو — ان کی چیزیں — کم — نہ کرو — اور — زمین میں فسادی — ہو کر فساد نہ کرو۔
۳۔ عملی سبق: ناپ تول — درست — ہے — تو — سب — ٹھیک — ہے۔"""
),
1559: (
"اللہ — کی بچی — ہوئی — چیز — تمہارے لیے — بہتر ہے — اگر — تم — مؤمن — ہو — اور — میں — تم — پر — کوئی نہیں رکھوالا — ہوں",
"""۱۔ اللہ کا دیا — حلال — سب سے بہتر؛ کاروبار میں توكل — کریں۔
۲۔ ’’بَقِيَّتُ اللَّهِ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ وَمَا أَنَا عَلَيْكُم بِحَفِيظٍ‘‘ — اللہ — کی بچی — ہوئی — چیز — تمہارے لیے — بہتر ہے — اگر — تم — مؤمن — ہو — اور — میں — تم — پر — کوئی نہیں رکھوالا — ہوں — یعنی اللہ کا جو حصّہ — تمہیں بچے — وہ — تمہارے لیے بہتر ہے — اگر تم مؤمن — ہو — اور میں — تم پر — کوئی رکھوالا — نہیں ہوں۔
۳۔ عملی سبق: حلال روزی — کی برکت — سب سے — بڑھ کر — ہے۔"""
),
1560: (
"انہوں نے — کہا — اے شعیبؑ — کیا — تمہاری نماز — تجھے — حکم — کرتی ہے — کہ — ہم — ان چیزوں — کو چھوڑ دیں — جن — کی — پرستش — ہمارے باپ دادا — کرتے تھے — یا — یہ — کہ ہم — اپنے اموال — میں — وہ — کریں جو — ہم — چاہیں — بے شک — تم — بہت — بردبار — اور — سمجھدار — ہو",
"""۱۔ قوم — شعیبؑ — کی نماز اور اللہ کا حکم — مذاق — اڑاتی ہے۔
۲۔ ’’قَالُوا يَا شُعَيْبُ أَصَلَاتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ آبَاؤُنَا أَوْ أَن نَّفْعَلَ فِي أَمْوَالِنَا مَا نَشَاءُ إِنَّكَ لَأَنتَ الْحَلِيمُ الرَّشِيدُ‘‘ — انہوں نے — کہا — اے شعیبؑ — کیا — تمہاری نماز — تجھے — حکم — کرتی ہے — کہ — ہم — ان چیزوں — کو چھوڑ دیں — جن — کی — پرستش — ہمارے باپ دادا — کرتے تھے — یا — یہ — کہ ہم — اپنے اموال — میں — وہ — کریں جو — ہم — چاہیں — بے شک — تم — بہت — بردبار — اور — سمجھدار — ہو — یعنی انہوں نے کہا — اے شعیبؑ — کیا تمہاری نماز — تمہیں — حکم — کرتی ہے — کہ ہم وہ چھوڑ دیں — جن کی — پرستش ہمارے باپ دادا — کرتے تھے — یا — یہ — کہ ہم اپنے اموال — میں — وہ کریں جو — ہم چاہیں — بے شک — تم — بہت — بردبار — اور — سمجھدار — ہو (یہ — طنز — تھا)۔
۳۔ عملی سبق: نیت — بد ہو تو — نیکی — بھی — مذاق بنتی ہے؛ دل — درست رکھیں۔"""
),
1561: (
"انہوں نے — کہا — اے — میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس نے — مجھے — اس — کی طرف سے — ایک اچھی — روزی — دی — اور — میں — اس — چیز — میں — تمہاری مخالفت نہیں کرنا چاہتا — جس سے — میں — تم — کو — روکتا ہوں — میں — صرف — حتی الامکان — اصلاح — چاہتا ہوں — اور — میری توفیق — صرف اللہ کی طرف — سے — ہے — اسی — پر — میں نے — بھروسہ کیا — اور — اسی کی طرف — میں — لوٹوں گا",
"""۱۔ شعیبؑ — آبرومندانہ — طریقہ سے — اصلاح — کی بات کرتے ہیں۔
۲۔ ’’قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَۃٍ مِّن رَّبِّي وَرَزَقَنِي مِنْهُ رِزْقًا حَسَنًا وَمَا أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَا أَنْهَاكُمْ عَنْهُ إِنْ أُرِيدُ إِلَّا الْإِصْلَاحَ مَا اسْتَطَعْتُ وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ‘‘ — انہوں نے — کہا — اے — میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس نے — مجھے — اس — کی طرف سے — ایک اچھی — روزی — دی — اور — میں — اس — چیز — میں — تمہاری مخالفت نہیں کرنا چاہتا — جس سے — میں — تم — کو — روکتا ہوں — میں — صرف — حتی الامکان — اصلاح — چاہتا ہوں — اور — میری توفیق — صرف اللہ کی طرف — سے — ہے — اسی — پر — میں نے — بھروسہ کیا — اور — اسی کی طرف — میں — لوٹوں گا — یعنی اے میری قوم — بتاو — اگر میں — اپنے رب کی دلیل — پر ہوں — اور وہ مجھے اچھی روزی — دے — اور میں — اس — چیز — میں — تمہاری مخالفت — نہیں کرنا چاہتا جس سے میں تم — کو — روکتا ہوں — میں صرف حتی الامکان اصلاح — چاہتا ہوں — میری توفیق — صرف اللہ کی طرف سے — ہے — اسی — پر — میں نے بھروسہ کیا — اور اسی کی طرف — میں — لوٹوں گا۔
۳۔ عملی سبق: اصلاح — خلوص — اور — اللہ کی توفیق — سے — ہوتی ہے۔"""
),
1562: (
"اور — اے میری قوم — مجھ سے — ضد — کرنا — تم — کو — اس بات — پر — نہ ڈال دے — کہ — تمہیں وہ — مصیبت — پہنچے — جو — نوحؑ — کی قوم — یا — ہودؑ — کی قوم — یا — صالحؑ — کی قوم — کو — پہنچی — اور — لوطؑ — کی قوم — بھی — تم سے — دور — نہیں",
"""۱۔ شعیبؑ — گزشتہ اقوام کی تباہی — سے خبردار کرتے ہیں۔
۲۔ ’’وَيَا قَوْمِ لَا يَجْرِمَنَّكُمْ شِقَاقِي أَن يُّصِيبَكُم مِّثْلُ مَا أَصَابَ قَوْمَ نُوحٍ أَوْ قَوْمَ هُودٍ أَوْ قَوْمَ صَالِحٍ وَمَا قَوْمُ لُوطٍ مِّنكُم بِبَعِيدٍ‘‘ — اور — اے میری قوم — مجھ سے — ضد — کرنا — تم — کو — اس بات — پر — نہ ڈال دے — کہ — تمہیں وہ — مصیبت — پہنچے — جو — نوحؑ — کی قوم — یا — ہودؑ — کی قوم — یا — صالحؑ — کی قوم — کو — پہنچی — اور — لوطؑ — کی قوم — بھی — تم سے — دور — نہیں — یعنی اے میری قوم — مجھ سے ضد — کرنا — تمہیں — اسی مصیبت — میں نہ ڈال دے — جو — نوحؑ، ہودؑ، صالحؑ اور لوطؑ کی قوم — کو پہنچی — اور — لوطؑ — کی قوم — بھی — تم سے — دور — نہیں۔
۳۔ عملی سبق: ماضی کی تباہی — سے عبرت — لو؛ ضد — چھوڑ دو۔"""
),
1563: (
"اور — اپنے رب سے — استغفار کرو — پھر — اس — کی طرف — توبہ کرو — بے شک — میرا رب — مہربان — محبت کرنے والا — ہے",
"""۱۔ استغفار اور توبہ — اللہ کی محبت — کا ذریعہ۔
۲۔ ’’وَاسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ‘‘ — اور — اپنے رب سے — استغفار کرو — پھر — اس — کی طرف — توبہ کرو — بے شک — میرا رب — مہربان — محبت کرنے والا — ہے — یعنی اپنے رب سے استغفار کرو — پھر اس کی طرف توبہ کرو؛ بے شک — میرا رب — رحیم ودود — ہے۔
۳۔ عملی سبق: اللہ — رحیم اور ودود — ہے؛ اس سے محبت — کرو اور مانگو۔"""
),
}
